// Spectral Ribbons (depth): each line is one recent spectrum, bass on the
// left and treble on the right. A line rises where a band is louder than
// that spectrum's average and dips where it is quieter. Every line starts and
// ends at the same two points; between them time runs into the screen, so
// older spectra arc back, shrink and fade. Attacks leave a bright line that
// recedes with its spectrum. Raised hands deepen the arc and move its crest.
const float PI=3.14159265;
const float ROWS=15.0;
vec4 spectrumTexel(float x,float row){
 return vrchSampleSignalTexture(0,vec2(x,(row+.5)/ROWS));
}
// One spectrum line. Only its height, slope, level and accent come from the row
// fetch; age and scale are recomputed from its index to keep few values live.
void spectrumLine(inout vec3 c,float k,float frac,float L,float D,float py,float y,float slope,float h,float cell,vec4 pick,float pix,float soft,float inside,float night){
 if(k>=L)return;
 float a=(k+frac)/L;
 float s=1.0/(1.0+D*a);
 float dist=abs(py-y)/length(vec2(slope,pix));
 float w=uParam_weight*.5*(.55+.45*s);
 // An accent widens a line by at most 1.9x: read it only for lines that can reach this pixel.
 if(w*1.9+.5*soft-dist<=0.0)return;
 float beat=dot(spectrumTexel(cell,14.0),pick)*uParam_accent;
 w*=1.0+.9*beat;
 float cover=clamp((w+.5*soft-dist)/soft,0.0,1.0);
 if(cover<=0.0)return;
 float alpha=cover*inside*uParam_ink*smoothstep(0.0,1.5,k+frac)*pow(1.0-a,1.8);
 alpha=min(1.0,alpha*(1.0+1.5*beat));
 vec3 hue=a<.5?mix(uParam_color_a.rgb,uParam_color_c.rgb,a*2.0):mix(uParam_color_c.rgb,uParam_color_b.rgb,a*2.0-1.0);
 hue=mix(hue,uParam_color_a.rgb,.5*smoothstep(.12,.45,abs(h)));
 hue=mix(hue,pow(max(hue,vec3(0.0)),vec3(.45)),night);
 hue=mix(hue,mix(vec3(1.0),hue,.35+.65*(1.0-night)),.75*beat);
 c=mix(c,hue,alpha);
}
// All rows of lines, oldest first. mainImage calls it with a constant line count
// for the default, so the compiler folds each row's ages, and with the parameter
// otherwise; both calls draw the same pixels.
vec3 ribbonRows(vec3 c,float L,float py,float tx,float uc,float rise,float amp,float frac,float rest,float soft,float hb,float edge,float D,float far,float pix,float inside,float night){
 int rowCount=int(ceil(L/4.0));
 for(int i=0;i<12;i++){
  if(i>=rowCount)break;
  float row=float(rowCount-1-i);
  vec4 k4=row*4.0+vec4(0.0,1.0,2.0,3.0);
  vec4 age=(k4+frac)/L;
  // The row test needs only its youngest and oldest line; the middle two follow once it passes.
  vec2 sxw=1.0/(1.0+D*age.xw);
  vec2 bxw=rise*(1.0-sxw)/(1.0-far);
  float reach=min(hb*amp*sxw.x,.2)+edge;
  if(py<bxw.x-reach||py>bxw.y+reach)continue;
  vec4 s4=vec4(sxw.x,1.0/(1.0+D*age.yz),sxw.y);
  vec4 base=vec4(bxw.x,rise*(1.0-s4.yz)/(1.0-far),bxw.y);
  float cell=(row+.5)/128.0;
  vec4 h4=spectrumTexel(tx,row)-spectrumTexel(cell,13.0);
  if(rest>0.0)h4+=rest*.16*sin(2.0*PI*(1.4*uc-.12*iTime)-age*7.0)*sin(PI*uc);
  vec4 lift=h4*amp*s4;
  lift*=inversesqrt(1.0+lift*lift/(.2*.2));
  vec4 y4=base+lift;
  vec4 d4=clamp(dFdx(y4),vec4(-6.0*pix),vec4(6.0*pix));
  // None of these four lines can cover a pixel farther than edge.
  if(all(greaterThan(abs(py-y4),vec4(edge))))continue;
  float k0=row*4.0;
  // One rolled loop over the four lines (its count comes from a parameter) keeps
  // a single copy of the line shading and fewer values live.
  int lineCount=int(min(L,4.0)+.5);
  for(int n=0;n<4;n++){
   if(n>=lineCount)break;
   int j=3-n;
   vec4 pick=vec4(equal(ivec4(0,1,2,3),ivec4(j)));
   spectrumLine(c,k0+float(j),frac,L,D,py,dot(y4,pick),dot(d4,pick),dot(h4,pick),cell,pick,pix,soft,inside,night);
  }
 }
 return c;
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 uv=fragCoord/iResolution.xy;
 float margin=.06;
 float u=(uv.x-margin)/(1.0-2.0*margin);
 float uc=clamp(u,0.0,1.0);
 float tx=(uc*127.0+.5)/128.0;
 float pix=1.0/iResolution.y;
 float du=1.0/(iResolution.x*(1.0-2.0*margin));
 float inside=clamp(u/du+.5,0.0,1.0)*clamp((1.0-u)/du+.5,0.0,1.0);
 float L=clamp(floor(uParam_lines+.5),16.0,48.0);
 float D=1.0+5.0*uParam_perspective;
 float far=1.0/(1.0+D);
 float origin=-.12;
 float py=uv.y-.5-origin;
 // Hands: their height deepens the arc, their centre moves its crest.
 float body=uParam_presence*uParam_steer;
 float crest=clamp(mix(.5,uParam_hand_x,.8*body),.22,.78);
 float w01=uc<crest?.5*uc/crest:.5+.5*(uc-crest)/(1.0-crest);
 float env=pow(sin(PI*w01),.7);
 float taper=smoothstep(0.0,.08,u)*smoothstep(1.0,.92,u);
 float rise=.5*uParam_depth*env*(1.0+.9*body*smoothstep(.3,.9,uParam_hand_y));
 float amp=.95*uParam_height*taper;
 vec3 c=uParam_background.rgb;
 float night=1.0-smoothstep(.02,.4,dot(c,vec3(.2126,.7152,.0722)));
 vec4 top=spectrumTexel(tx,12.0);
 float frac=top.g;
 // Between songs a slow swell keeps flowing back through the lines.
 float rest=1.0-smoothstep(.03,.15,top.b);
 float soft=1.0+.6*uParam_smooth;
 // Exact skip bounds: |level - mean| never exceeds this column's maximum or
 // the largest mean, the soft limit caps a lift at 0.2, and a line can only
 // cover pixels within its widest stroke over the steepest clamped slope.
 float hb=max(top.r,top.b)+.16*rest;
 float edge=((uParam_weight*.95+.5*soft)*6.1+2.0)*pix;
 float reachMax=min(hb*amp,.2)+edge;
 bool covered=u>-du&&u<1.0+du&&py>-reachMax&&py<rise+reachMax;
 if(covered){
  if(L==32.0)c=ribbonRows(c,32.0,py,tx,uc,rise,amp,frac,rest,soft,hb,edge,D,far,pix,inside,night);
  else c=ribbonRows(c,L,py,tx,uc,rise,amp,frac,rest,soft,hb,edge,D,far,pix,inside,night);
 }
 fragColor=vec4(c,1.0);
}
